(1, 'Home', 'Home', '', 'home', 'Index'),
(2, 'Water Treatment Plant', 'Water Treatment Plant', 'A.png', 'water_treatment_plant', 'WaterTreatment'),
(3, 'Water Softener', 'Water Softener', 'B.png', 'water_softener', 'WaterSoftener'),
(4, 'RO-Drinking Water', 'RO-Drinking Water', 'C.png', 'ro_drinking_water', 'DrinkingWater'),
(5, 'News', 'News', '', 'news', 'News');
