INSERT INTO `product_descriptions` (`id`, `product_id`, `position`, `title`, `subtitle`, `description`, `images`) VALUES
(5, 1, 1, 'ONYX WATER DISPENSER', '', '<p>Pure, filtered water with four temperature settings at the touch of a button.</p>\n', '1060271210A.png'),
(6, 1, 2, 'MHW', '', '<p>\"Love the Onyx Water Dispenser! It fits perfectly in my kitchen and provides fresh, clean water. Easy to use and energy-efficient.\"</p>\n', NULL),
(7, 1, 2, 'AYP', '', '<p>\"The Onyx Water Dispenser is sleek, practical, and keeps water fresh. Perfect for my busy lifestyle!\"</p>\r\n', NULL),
(8, 1, 2, 'TP', '', '<p>\"I trust the Onyx for my family&#39;s health. It&#39;s simple, easy to use, and gives clean water every time.\"</p>\r\n', NULL),
(9, 1, 3, '5 Stage Filtration System', '', '<p>Each filtration stage removes impurities enhancing water quality for pure refreshing drinking water. Onyx also restores essential minerals, delivering clean healthy, and great tasting water.</p>\r\n', '1813987162I.png'),
(10, 1, 4, 'UV Sterilization', '', '<p>A cutting-edge technology that effectively eliminates harmful bacteria and viruses from your water. By using ultraviolet light, this process disrupts the DNA of microorganisms, rendering them inactive and unable to reproduce.</p></br>\n\n<p><font style=\"color:blue;\">*Built in UV-C lamp for 24h disinfection and sterilization of the water and tank</font></p>', '1680788711J.png'),
(11, 1, 5, 'Just click, you get it', '', '<h3>4 Temperature Options</h3>\n\n<font class=\"font-bold text-blue-500\">Cold</font>, <font class=\"font-bold text-green-500\">Ambient</font>, <font class=\"font-bold text-yellow-500\">Warm</font>, <font class=\"font-bold text-red-500\">Hot</font>.\n\n<p>Whatever you want, just click in an instant.</p>', '769092893P.png'),
(12, 1, 6, 'Ensuring Safety for Your Family', 'Onyx Water Dispenser with Child Lock Feature', '<p>Onyx Water Dispenser comes with a Child Lock feature specially designed to protect your family. This feature prevents unwanted access, especially by children, by automatically locking the water dispensing button. As a result, you can enjoy the convenience of using the water dispenser without worrying about potential accidents, providing extra safety for every family member.</p>\r\n', '1506166092Q.png'),
(13, 1, 7, 'Instant Hydration, Endless Purity', 'Wherever You Are.', 'With the Onyx Water Dispenser, enjoy pure, refreshing water at the touch of a button, anytime and anywhere. Its advanced filtration technology ensures that every drop is free from impurities, providing you with safe and clean hydration whenever you need it. Whether at home, in the office, or on the go, Onyx brings you instant access to fresh water, ensuring convenience and purity with every sip.', '260484010R2.png'),
(14, 1, 8, 'Ready to embrace a life of ease?', '', '<p>The Onyx Water Dispenser is designed to make your life easier while paving the way for a healthier future. With its advanced features like multiple water temperature options, UV sterilization, and high-quality filtration, Onyx ensures you always have access to pure, clean water at your fingertips. Its smart technology, including the TDS display and compressor cooling system, provides both convenience and peace of mind, offering you water that’s not only refreshing but also safe.</p></br>\n\n<p>Embrace a lifestyle of ease and health with Onyx, where innovation meets wellness for a brighter tomorrow.</p>', '1733768858S.jpg'),
(15, 1, 9, 'Contact us', '', 'Please fill out of the form below and someone will get in touch with you shortly\n', '1108342015S.jpg'),
(16, 3, 1, 'AQUILLA 500G', 'REVERSE OSMOSIS', '<p>Pure, Efficient, Reliable.</p>\r\n', '2066543689AB.png'),
(17, 3, 3, 'Aquilla 500G', 'Second to none', 'The Aquilla 500G water filtration system delivers exceptional performance with advanced Reverse Osmosis (RO) technology, removing contaminants like chlorine, bacteria, and heavy metals. Its sleek, compact design ensures easy filter replacement and reliable, long-lasting filtration for your home or business.', '381636725T.png'),
(18, 3, 5, '6 Stages Filtration', '', 'Ensuring the removal of harmful impurities such as chlorine, bacteria, heavy metals, and other contaminants. Each stage is designed to target specific particles, from pre-filtration to advanced post-filtration, providing you with the highest level of purity and safety.', 'G3.png'),
(19, 3, 6, 'Compact & Stylish', 'Fits neatly under any sink', '', 'Z.png'),
(20, 3, 9, 'Contact us', '', 'Please fill out of the form below and someone will get in touch with you shortly\r\n', 'AA.png'),
(21, 3, 8, 'Aquilla 500G : Trust in Every Drop', '500 GPD of Pure, Remineralized Water Right at Your Fingertips', '<p>Aqualife’s Aquilla 500G produces up to 500 gallons of perfectly pure water every day—removing 99% of impurities, then restoring healthy calcium and magnesium for balanced pH and great taste. Say goodbye to single-use bottles, lower your utility costs, and drink with confidence, drop after drop.</p>\r\n\r\n<p> </p>\r\n\r\n<h2><strong>Features : </strong></h2>\r\n\r\n<p>• 500 GPD Capacity</p>\r\n\r\n<p>• 6 Stage Filtration</p>\r\n\r\n<p>• 2:1 Pure-to-Waste</p>\r\n\r\n<p>• Compact Design</p>\r\n\r\n<p>• Swivel Faucet</p>\r\n', 'P.png'),
(22, 3, 4, ' Durable 304 Stainless Steel', '', '<p>Durable 304 Stainless Steel</p>\r\n', '953678737U.png'),
(23, 3, 4, '90° Switch left and right', '', '<p>90° Switch left and right</p>\r\n', '1117476548V.png'),
(24, 3, 4, '360° Swivel Faucet', '', '<p>360° Swivel Faucet</p>\r\n', '598227154W.png'),
(25, 3, 4, 'Fast to get a fresh water', '', '<p>Fast to get a fresh water</p>\r\n', '1775758195X.png'),
(26, 3, 7, 'Aquilla 500G di dapur', '', '<p>Aquilla 500G di dapur</p>\r\n', '1012474598L2.png'),
(27, 3, 7, 'Pria minum air', '', '<p>Pria minum air</p>\r\n', '1803426527M.jpg'),
(28, 3, 7, 'Memegang gelas air', '', '<p>Memegang gelas air</p>\r\n', '1208440923N.jpeg');
