INSERT INTO `product_images` (`id`, `product_id`, `title`, `description`, `images`, `title_category`, `subtitle_category`, `position`) VALUES
(1, 1, 'Smart LED & TDS Display', 'Real-time TDS monitoring ensures water purity at every stage of filtration.', 'onyxB.png', '', '', 'RIGHT'),
(2, 1, 'Adaptable Water Supply', 'Easily switch between standalone tank mode or direct tap connection for unmatched convenience and flexibility.', 'onyxD.png', '', '', 'LEFT'),
(3, 1, 'Compressor Cooling System', 'Enjoy water with an ideal temperature of 5-8?C thanks to Compressor Cooling System technology providing comfort for you and your family.', 'onyxF.png', '', '', 'RIGHT'),
(4, 1, '5s Instant Heat', 'Enjoy hot water in just 5 seconds, perfect for your favorite hot beverages without the wait.', 'onyxL.png', '', '', 'LEFT'),
(5, 1, 'High Flux RO Membrane', 'The high efficiency RO membrane provides pure water free from harmful contaminants ensuring health and safety for your entire family.', 'onyxN.png', '', '', 'LEFT'),
(6, 3, 'EFFICIENT WATER SAVING', 'Fill Your Cup Instanly With 1,3 L/min Flow Rate', 'Q1.png', '', '', 'LEFT'),
(7, 3, 'DUAL WATER OUTPUT', 'Enjoy the convenience of Dual Water Output ? get clean and drinking water for all your needs, anytime!', 'R1.png', '', '', 'RIGHT'),
(8, 3, 'QUICK PLUG AND PLAY INSTALLATION', 'When replacing the filter, the filter can be changed directly without lifting the machine', 'S.png', '', '', 'LEFT');
INSERT INTO `reviews` (`id`, `name`, `description`, `rate`, `created_at`) VALUES
(3, 'Nicole S', 'Amazing customer service. Their admin is very easy to communicate with and they are always responsive.', 5, '2025-08-09 15:21:08'),
(5, 'Juliani', 'Since I started using Aqualife I never have to buy bottled water outside anymore', 5, '2025-08-17 05:29:43'),
(6, 'Kevin Saputro', 'Great owner, great product and great service. Totally recommended if you need any solutions on water filter/RO.', 5, '2025-08-17 05:29:58'),
(7, 'Kevin S', 'Great service and great owner. Recommended for all your water filter needs.', 5, '2025-08-17 05:30:12');
